window.products.push({"id":335895,"name":"Mann Lake DC130 para-Moth Wax Moth Control Canister, 1-Pound","category":"homeandappliances","retail price":38.9,"sale price":null,"image":"https://m.media-amazon.com/images/I/71oHBb0T0qL._AC_SL1400_.jpg","description":"Para-Moth is used to control wax moths in stored supers. Place 3-ounce (6 tablespoons) on a paper plate and place on top bars of uppermost super. Stack 5 deep supers or 9 shallow supers and cover with a tarp. Equipment should be aired for several days before use. Do not use in the hive or with cut comb honey or un-extracted combs of honey. Comes in 1-pound canister. Measures 3-3/4-inch diameter by 5-7/8-inch height.","images":["https://m.media-amazon.com/images/I/71oHBb0T0qL._AC_SL1400_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Mann Lake","source_asin":"B0BW97PJCZ","category_path":"Home & Kitchen"},"sku":"BM-335895","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0BW97PJCZ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0BW97PJCZ","price_pending":true,"merchant_ready":false});
